param([ValidateSet('x86', 'x64')][string]$CompileArchitecture)
$ErrorActionPreference = 'Stop'
$repoRoot = Split-Path $PSScriptRoot -Parent
$source = Join-Path $repoRoot '.deps/dxvk-remix'
$testDir = Join-Path $repoRoot '.deps/overlay-presenter-test'
New-Item -ItemType Directory -Force $testDir | Out-Null
if ($CompileArchitecture) {
  . (Join-Path $source 'bridge/build_common.ps1')
  SetupVS -Platform $CompileArchitecture -VcVarsVer '14.29'
  Push-Location $testDir
  try {
    & cl.exe /nologo /std:c++17 /EHsc /W4 /WX /LD "$repoRoot/tests/overlay_fake_reshade.cpp" "/Fe:fake-$CompileArchitecture.dll" /link "/DEF:$repoRoot/tests/overlay_fake_reshade.def"
    if ($LASTEXITCODE -ne 0) { throw "ReShade ABI test double compilation failed for $CompileArchitecture" }
    & cl.exe /nologo /std:c++17 /EHsc /W4 /WX "/I$source/bridge/src/server" "$repoRoot/tests/overlay_presenter.cpp" user32.lib "/Fe:overlay-$CompileArchitecture.exe"
    if ($LASTEXITCODE -ne 0) { throw "Overlay presenter compilation failed for $CompileArchitecture" }
  } finally { Pop-Location }
} else {
  foreach ($arch in @('x86', 'x64')) {
    & powershell.exe -NoProfile -File $PSCommandPath -CompileArchitecture $arch
    if ($LASTEXITCODE -ne 0) { throw "Overlay presenter compilation failed for $arch" }
  }
  & (Join-Path $testDir 'overlay-x86.exe') (Join-Path $testDir 'overlay-x64.exe')
  if ($LASTEXITCODE -ne 0) { throw 'x86 parent / x64 presenter failed' }
  & (Join-Path $testDir 'overlay-x64.exe') (Join-Path $testDir 'overlay-x86.exe')
  if ($LASTEXITCODE -ne 0) { throw 'x64 parent / x86 presenter failed' }
}
